    83	    /**
    84	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    85	     * reservation was never paid, so nothing comes back).
    86	     */
    87	    public synchronized Reservation cancel(long reservationId) {
    88	        Reservation reservation = find(reservationId);
    89	        if (reservation.status() != ReservationStatus.PENDING
    90	                && reservation.status() != ReservationStatus.CONFIRMED) {
    91	            throw notAllowed(reservation, "cancel");
    92	        }
    93	        BigDecimal refund = switch (reservation.ratePlan()) {
    94	            case STANDARD -> reservation.amountPaid();
    95	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    96	        };
    97	        reservation.cancel(refund);
    98	        store.update(reservation);
    99	        Room room = roomOf(reservation);
   100	        for (ReservationListener listener : listeners) {
   101	            listener.onCancellation(reservation, room);
   102	        }
   103	        return reservation;
   104	    }
